// The layer store. Undo of an add calls remove(); redo adds the layer back with the same id.
// The workspace keeps its selection across undo and redo.
export class Store {
  constructor() {
    this.layers = new Map();
  }

  add(layer) {
    this.layers.set(layer.id, layer);
  }

  remove(id) {
    this.layers.delete(id);
  }

  get(id) {
    return this.layers.get(id);
  }
}

